// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.ui.screensimport androidx.compose.foundation.backgroundimport androidx.compose.foundation.borderimport androidx.compose.foundation.clickableimport androidx.compose.foundation.layout.Arrangementimport androidx.compose.foundation.layout.Boximport androidx.compose.foundation.layout.Columnimport androidx.compose.foundation.layout.Rowimport androidx.compose.foundation.layout.Spacerimport androidx.compose.foundation.layout.fillMaxWidthimport androidx.compose.foundation.layout.paddingimport androidx.compose.foundation.layout.sizeimport androidx.compose.foundation.lazy.grid.GridCellsimport androidx.compose.foundation.lazy.grid.LazyVerticalGridimport androidx.compose.foundation.lazy.grid.itemsimport androidx.compose.foundation.shape.RoundedCornerShapeimport androidx.compose.material3.MaterialThemeimport androidx.compose.material3.Textimport androidx.compose.runtime.Composableimport androidx.compose.runtime.getValueimport androidx.compose.runtime.mutableStateOfimport androidx.compose.runtime.rememberimport androidx.compose.runtime.setValueimport androidx.compose.ui.Alignmentimport androidx.compose.ui.Modifierimport androidx.compose.ui.text.font.FontWeightimport androidx.compose.ui.unit.dpimport com.roshan.persona.ui.components.PersonaAvatarimport com.roshan.persona.ui.theme.personaColor/** * Persona summary — passed in from the Persona module. */data class PersonaSummary(    val id: String,    val displayName: String,    val tagline: String,    val archetype: String,)/** * Persona Switcher sheet — choose from 9 built-in personas. * * The list of personas is provided by the host (from BuiltInPersonas in :feature:persona). * On selection, [onPersonaSelected] is called with the persona ID — the host * persists the choice and updates the active persona in the Brain. */@Composablefun PersonaSwitcherSheet(    personas: List<PersonaSummary>,    activePersonaId: String,    onPersonaSelected: (String) -> Unit,    modifier: Modifier = Modifier,) {    var selectedId by remember { mutableStateOf(activePersonaId) }    val selected = personas.firstOrNull { it.id == selectedId }    Column(        modifier = modifier            .fillMaxWidth()            .background(                color = MaterialTheme.colorScheme.surface,                shape = RoundedCornerShape(topStart = 24.dp, topEnd = 24.dp),            )            .padding(20.dp),    ) {        Text(            text = "Choose Your Persona",            style = MaterialTheme.typography.headlineLarge,            fontWeight = FontWeight.Bold,            color = MaterialTheme.colorScheme.onSurface,        )        Spacer(modifier = Modifier.size(20.dp))        // Active persona card        if (selected != null) {            val accentColor = personaColor(selected.id)            Row(                modifier = Modifier                    .fillMaxWidth()                    .background(                        color = accentColor.copy(alpha = 0.1f),                        shape = RoundedCornerShape(16.dp),                    )                    .border(                        width = 1.dp,                        color = accentColor.copy(alpha = 0.4f),                        shape = RoundedCornerShape(16.dp),                    )                    .padding(16.dp),                verticalAlignment = Alignment.CenterVertically,            ) {                PersonaAvatar(                    personaId = selected.id,                    displayName = selected.displayName,                    size = 64.dp,                )                Spacer(modifier = Modifier.size(16.dp))                Column {                    Text(                        text = selected.displayName,                        style = MaterialTheme.typography.titleLarge,                        fontWeight = FontWeight.SemiBold,                        color = MaterialTheme.colorScheme.onSurface,                    )                    Text(                        text = selected.tagline,                        style = MaterialTheme.typography.bodyMedium,                        color = MaterialTheme.colorScheme.onSurfaceVariant,                    )                    Text(                        text = "Archetype: ${selected.archetype}",                        style = MaterialTheme.typography.labelSmall,                        color = MaterialTheme.colorScheme.onSurfaceVariant,                    )                }            }        }        Spacer(modifier = Modifier.size(20.dp))        // Grid of all personas        LazyVerticalGrid(            columns = GridCells.Fixed(3),            modifier = Modifier.fillMaxWidth(),            horizontalArrangement = Arrangement.spacedBy(12.dp),            verticalArrangement = Arrangement.spacedBy(12.dp),        ) {            items(personas) { persona ->                val isSelected = persona.id == selectedId                val accentColor = personaColor(persona.id)                Column(                    modifier = Modifier                        .clickable { selectedId = persona.id }                        .background(                            color = if (isSelected) accentColor.copy(alpha = 0.15f) else MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.4f),                            shape = RoundedCornerShape(16.dp),                        )                        .border(                            width = if (isSelected) 2.dp else 0.dp,                            color = if (isSelected) accentColor else androidx.compose.ui.graphics.Color.Transparent,                            shape = RoundedCornerShape(16.dp),                        )                        .padding(12.dp),                    horizontalAlignment = Alignment.CenterHorizontally,                ) {                    PersonaAvatar(                        personaId = persona.id,                        displayName = persona.displayName,                        size = 48.dp,                    )                    Spacer(modifier = Modifier.size(8.dp))                    Text(                        text = persona.displayName,                        style = MaterialTheme.typography.labelMedium,                        fontWeight = FontWeight.SemiBold,                        color = MaterialTheme.colorScheme.onSurface,                    )                    Text(                        text = persona.archetype,                        style = MaterialTheme.typography.labelSmall,                        color = MaterialTheme.colorScheme.onSurfaceVariant,                    )                }            }        }        Spacer(modifier = Modifier.size(20.dp))        // Use button        com.roshan.persona.ui.components.NeoButton(            text = "Use Selected Persona",            onClick = { onPersonaSelected(selectedId) },            modifier = Modifier.fillMaxWidth(),        )    }}